	internal readonly struct Entry
	{
		internal readonly Homm3UnitLawClassifier.Fact Gunpowder;
		internal readonly Homm3UnitLawClassifier.Fact Shooter;
		internal readonly Homm3UnitLawClassifier.Fact Melee;
		internal readonly Homm3UnitLawClassifier.Fact Construct;
		internal readonly Homm3UnitLawClassifier.Fact Elemental;
		internal readonly Homm3UnitLawClassifier.Fact Undead;
		internal readonly Homm3UnitLawClassifier.Fact Living;
		internal readonly Homm3UnitLawClassifier.Fact GatedOrSummoned;
		internal readonly Homm3UnitLawClassifier.Fact CorpseProducing;

		internal Entry(
			Homm3UnitLawClassifier.Fact gunpowder = Homm3UnitLawClassifier.Fact.Unknown,
			Homm3UnitLawClassifier.Fact shooter = Homm3UnitLawClassifier.Fact.Unknown,
			Homm3UnitLawClassifier.Fact melee = Homm3UnitLawClassifier.Fact.Unknown,
			Homm3UnitLawClassifier.Fact construct = Homm3UnitLawClassifier.Fact.Unknown,
			Homm3UnitLawClassifier.Fact elemental = Homm3UnitLawClassifier.Fact.Unknown,
			Homm3UnitLawClassifier.Fact undead = Homm3UnitLawClassifier.Fact.Unknown,
			Homm3UnitLawClassifier.Fact living = Homm3UnitLawClassifier.Fact.Unknown,
			Homm3UnitLawClassifier.Fact gatedOrSummoned = Homm3UnitLawClassifier.Fact.Unknown,
			Homm3UnitLawClassifier.Fact corpseProducing = Homm3UnitLawClassifier.Fact.Unknown)
		{
			Gunpowder = gunpowder;
			Shooter = shooter;
			Melee = melee;
			Construct = construct;
			Elemental = elemental;
			Undead = undead;
			Living = living;
			GatedOrSummoned = gatedOrSummoned;
			CorpseProducing = corpseProducing;
		}
	}

	internal static bool TryGet(string sid, out Entry entry)
	{
		entry = default;
		return !string.IsNullOrEmpty(sid) && Entries.TryGetValue(sid, out entry);
	}
